import { type SynapseEnhancedHttpClient } from "../utils/http.ts";
import { ErrorCode } from "../utils/error-codes.ts";
import { validateMessageId, validateRoomId, validateUserId } from "../utils/validator.ts";
import { EnhancedApi, useMultipartVoiceUpload } from "../constants/api.ts";
import type {
    IVoiceMessage,
    IVoiceInfo,
    IVoiceUploadParams,
    IVoiceConvertParams,
    IVoiceOptimizeParams,
    IConvertResult,
    IOptimizeResult,
    IVoiceUserStats,
} from "../models/types.ts";
import { handleApiResponse } from "../utils/response-formatter.ts";
import { BaseApi } from "../utils/base-api.ts";

// Maximum file size for base64 encoding (100MB) to prevent memory exhaustion
const MAX_FILE_SIZE_FOR_BASE64 = 100 * 1024 * 1024; // 100MB in bytes

export interface IVoiceConfig {
    supported_formats: string[];
    max_duration_seconds: number;
    max_file_size_bytes: number;
    default_format: string;
    default_quality: string;
    features: {
        conversion: boolean;
        optimization: boolean;
        premium: string[];
    };
}

export class VoiceApi extends BaseApi {
    public constructor(httpClient: SynapseEnhancedHttpClient) {
        super(httpClient);
    }

    /**
     * Get voice configuration
     */
    public async getConfig(): Promise<IVoiceConfig> {
        const response = await this.httpClient.get<{
            status: string;
            data?: IVoiceConfig;
            error?: string;
        }>(EnhancedApi.VOICE_CONFIG);

        return handleApiResponse(response, "Failed to get voice config");
    }

    /**
     * Upload and process a voice message
     *
     * Supports two upload protocols:
     * 1. Multipart/form-data (standard Matrix)
     * 2. JSON base64 (Synapse Rust)
     *
     * The protocol is automatically selected based on the backend profile.
     */
    public async upload(params: IVoiceUploadParams): Promise<IVoiceMessage> {
        const useMultipart = useMultipartVoiceUpload();
        const format = params.format || "ogg";

        if (useMultipart) {
            // Standard multipart/form-data upload
            const queryParams: Record<string, string> = {
                ext: `.${format}`,
            };

            if (params.quality) {
                queryParams.quality = params.quality;
            }

            const headers = {
                "Content-Type": "multipart/form-data; boundary=----WebKitFormBoundaryWorkaround",
            };

            const response = await this.httpClient.request<{
                status: string;
                data?: IVoiceMessage;
                error?: string;
            }>(EnhancedApi.VOICE_UPLOAD, {
                method: "POST",
                body: params.file,
                queryParams,
                headers,
            });

            return handleApiResponse(response, "Failed to upload voice message");
        } else {
            // JSON base64 upload (Synapse Rust)
            const fileBuffer = await this.fileToBuffer(params.file);
            const base64Data = this.bufferToBase64(fileBuffer);

            const body: Record<string, unknown> = {
                file_data: base64Data,
                format,
                filename: params.filename || `voice_${Date.now()}.${format}`,
                size: fileBuffer.byteLength,
                mime_type: this.getMimeType(format),
            };

            if (params.quality) {
                body.quality = params.quality;
            }

            if (params.duration_ms) {
                body.duration_ms = params.duration_ms;
            }

            const response = await this.httpClient.post<{
                status: string;
                data?: IVoiceMessage;
                error?: string;
            }>(EnhancedApi.VOICE_UPLOAD, body);

            return handleApiResponse(response, "Failed to upload voice message");
        }
    }

    /**
     * Convert File/Blob to ArrayBuffer
     */
    private async fileToBuffer(file: File | Blob | ArrayBuffer): Promise<ArrayBuffer> {
        if (file instanceof ArrayBuffer) {
            return file;
        }
        return await file.arrayBuffer();
    }

    /**
     * Convert ArrayBuffer to base64 string
     * @param buffer - The ArrayBuffer to convert
     * @returns Base64 encoded string
     * @throws SynapseEnhancedError if buffer size exceeds limit
     */
    private bufferToBase64(buffer: ArrayBuffer): string {
        // Check buffer size to prevent memory exhaustion attacks
        if (buffer.byteLength > MAX_FILE_SIZE_FOR_BASE64) {
            throw this.createError(
                `File size (${buffer.byteLength} bytes) exceeds maximum allowed size (${MAX_FILE_SIZE_FOR_BASE64} bytes) for base64 encoding`,
                ErrorCode.INVALID_PARAM,
            );
        }

        const bytes = new Uint8Array(buffer);
        let binary = "";
        for (let i = 0; i < bytes.byteLength; i++) {
            binary += String.fromCharCode(bytes[i]);
        }
        return btoa(binary);
    }

    /**
     * Get MIME type for audio format
     */
    private getMimeType(format: string): string {
        const mimeTypes: Record<string, string> = {
            ogg: "audio/ogg",
            mp3: "audio/mpeg",
            m4a: "audio/mp4",
            wav: "audio/wav",
            opus: "audio/opus",
            aac: "audio/aac",
            flac: "audio/flac",
        };
        return mimeTypes[format] || "audio/ogg";
    }

    /**
     * Get voice message info
     */
    public async getInfo(messageId: string): Promise<IVoiceInfo | null> {
        try {
            const response = await this.httpClient.get<{
                status: string;
                data?: IVoiceInfo;
                error?: string;
            }>(EnhancedApi.VOICE_DETAIL.replace("{messageId}", encodeURIComponent(messageId)));

            // Check for failed status before handleApiResponse throws
            if (response.data?.status === "failed" || !response.data?.data) {
                return null;
            }

            return handleApiResponse(response, "Failed to get voice info");
        } catch {
            return null;
        }
    }

    /**
     * Convert voice message to another format
     */
    public async convert(params: IVoiceConvertParams): Promise<IConvertResult> {
        const body: Record<string, unknown> = {
            url: params.url,
            message_id: params.message_id,
            target_format: params.target_format,
        };

        if (params.bitrate !== undefined) {
            body.bitrate = params.bitrate;
        }

        const response = await this.httpClient.post<{
            status: string;
            data?: IConvertResult;
            error?: string;
        }>(EnhancedApi.VOICE_CONVERT, body);

        return handleApiResponse(response, "Failed to convert voice message");
    }

    /**
     * Optimize voice message file size
     */
    public async optimize(params: IVoiceOptimizeParams): Promise<IOptimizeResult> {
        const body: Record<string, unknown> = {
            url: params.url,
            message_id: params.message_id,
        };

        if (params.target_size_mb !== undefined) {
            body.target_size_mb = params.target_size_mb;
        }

        if (params.bitrate !== undefined) {
            body.bitrate = params.bitrate;
        }

        const response = await this.httpClient.post<{
            status: string;
            data?: IOptimizeResult;
            error?: string;
        }>(EnhancedApi.VOICE_OPTIMIZE, body);

        return handleApiResponse(response, "Failed to optimize voice message");
    }

    public async delete(messageId: string): Promise<boolean> {
        validateMessageId(messageId);

        const response = await this.httpClient.delete<{
            status: string;
            error?: string;
        }>(EnhancedApi.VOICE_DELETE.replace("{messageId}", encodeURIComponent(messageId)));

        handleApiResponse(response, "Failed to delete voice message");
        return true;
    }

    public async getUserMessages(userId: string): Promise<IVoiceInfo[]> {
        validateUserId(userId);

        const response = await this.httpClient.get<{
            status: string;
            data?: {
                voice_messages?: IVoiceInfo[];
            };
            error?: string;
        }>(EnhancedApi.VOICE_USER.replace("{userId}", encodeURIComponent(userId)));

        const data = handleApiResponse(response, "Failed to get user voice messages");
        return data.voice_messages || [];
    }

    public async getRoomMessages(roomId: string): Promise<IVoiceInfo[]> {
        validateRoomId(roomId);

        const response = await this.httpClient.get<{
            status: string;
            data?: {
                voice_messages?: IVoiceInfo[];
            };
            error?: string;
        }>(EnhancedApi.VOICE_ROOM.replace("{roomId}", encodeURIComponent(roomId)));

        const data = handleApiResponse(response, "Failed to get room voice messages");
        return data.voice_messages || [];
    }

    public async getUserStats(userId: string): Promise<IVoiceUserStats> {
        validateUserId(userId);

        const response = await this.httpClient.get<{
            status: string;
            data?: {
                stats?: IVoiceUserStats;
            };
            error?: string;
        }>(EnhancedApi.VOICE_USER_STATS.replace("{userId}", encodeURIComponent(userId)));

        const data = handleApiResponse(response, "Failed to get user voice stats");
        return data.stats!;
    }

    public getDownloadUrl(messageId: string): string {
        const validation = validateMessageId(messageId);
        if (!validation.valid) {
            throw this.createError(validation.error || "Invalid message ID", ErrorCode.INVALID_PARAM);
        }
        return EnhancedApi.VOICE_DOWNLOAD.replace("{messageId}", encodeURIComponent(messageId));
    }
}
